//! **Positioned v3** (`tests/fixtures/v3/<name>.json`):
//! [`PositionedGraphSnapshot`] generated by the current `ngrams` oracle.
//! Loaded and validated by [`load_v3`]; there is no graph seeding for v3.
use super::{fixtures_dir, read_json};
pub use ngrams::output::PositionedGraphSnapshot;
use std::path::PathBuf;

/// Directory of positioned v3 fixtures generated by the `ngrams` CLI.
pub fn v3_dir() -> PathBuf {
    fixtures_dir().join("v3")
}

/// Load and validate a positioned v3 fixture.
pub fn load_v3(name: &str) -> PositionedGraphSnapshot {
    let path = v3_dir().join(format!("{name}.json"));
    let fixture: PositionedGraphSnapshot = read_json(&path);
    fixture
        .validate()
        .unwrap_or_else(|error| panic!("{}: invalid v3 fixture: {error}", path.display()));
    fixture
}
